import React from "react";
import withNavigation from "../utils/withNavigation";
import axiosInstance from "../configurations/instance";

class AddChecker extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      name: "",
      surname: "",
      email: "",
      role: "Checker",
      password: "",
      confirmPassword: "",
    };
  }

  handleSubmit = () => {
    const { name, surname, email, role, password, confirmPassword } = this.state;

    // Проверка совпадения паролей
    if (password !== confirmPassword) {
      alert("Пароли не совпадают. Попробуйте снова.");
      return;
    }

    axiosInstance
      .post("/checker/create-checker", { name, surname, email, role, password })
      .then((response) => {
        console.log("Проверяющий создан:", response.data);

        localStorage.setItem("email", email);
        localStorage.setItem("token", response.data.token);

        this.props.navigate("/verify-checker");
      })
      .catch((error) => {
        console.error("Ошибка при создании проверяющего:", error);
      });
  };

  render() {
    return (
      <div>
        <h1>Добро Пожаловать!</h1>
        <h3>Заполните данные для регистрации</h3>
        <form>
          <div className="name-surname">
            <div>
              <label htmlFor="name">Введите ваше имя</label>
              <input
                id="name"
                value={this.state.name}
                onChange={(e) => this.setState({ name: e.target.value })}
                placeholder="Имя"
              />
            </div>
            <div>
              <label htmlFor="surname">Введите вашу фамилию</label>
              <input
                id="surname"
                value={this.state.surname}
                onChange={(e) => this.setState({ surname: e.target.value })}
                placeholder="Фамилия"
              />
            </div>
          </div>

          <label htmlFor="email">Введите вашу почту</label>
          <input
            id="email"
            value={this.state.email}
            onChange={(e) => this.setState({ email: e.target.value })}
            placeholder="Почта"
          />

          <label htmlFor="password">Введите пароль</label>
          <input
            id="password"
            type="password"
            value={this.state.password}
            onChange={(e) => this.setState({ password: e.target.value })}
            placeholder="Пароль"
          />

          <label htmlFor="confirmPassword">Повторите пароль</label>
          <input
            id="confirmPassword"
            type="password"
            value={this.state.confirmPassword}
            onChange={(e) => this.setState({ confirmPassword: e.target.value })}
            placeholder="Повторный пароль"
          />

          <button type="button" onClick={this.handleSubmit}>
            Создать
          </button>
        </form>
      </div>
    );
  }
}

export default withNavigation(AddChecker);
